package com.portal.settings.repository;

import com.portal.settings.entity.NotificationPreference;
import org.springframework.data.repository.CrudRepository;
import org.springframework.data.rest.core.annotation.RepositoryRestResource;
import org.springframework.security.access.prepost.PostAuthorize;
import org.springframework.security.access.prepost.PreAuthorize;
import java.util.Optional;

@RepositoryRestResource(path = "notification-preferences")
public interface NotificationPreferenceRepository extends CrudRepository<NotificationPreference, Long> {

    @Override
    @PostAuthorize("returnObject.isPresent() and returnObject.get().userId.equals(principal.name)")
    Optional<NotificationPreference> findById(Long id);

    @Override
    @PreAuthorize("#entity.userId.equals(principal.name)")
    <S extends NotificationPreference> S save(S entity);
}
